type reviewLegacyCodec struct{}
func (reviewLegacyCodec) Name() string { return "proto" }
func (reviewLegacyCodec) Marshal(v any) ([]byte, error) { return oldproto.Marshal(v.(oldproto.Message)) }
func (reviewLegacyCodec) Unmarshal(data []byte, v any) error { return oldproto.Unmarshal(data, v.(oldproto.Message)) }

type reviewCaptureLogger struct { entries chan *binlogpb.GrpcLogEntry }
func (l reviewCaptureLogger) GetMethodLogger(string) binlog.MethodLogger { return l }
func (l reviewCaptureLogger) Log(_ context.Context, config binlog.LogEntryConfig) {
    l.entries <- binlog.NewTruncatingMethodLogger(1024, 1024).Build(config)
}

func TestReviewLegacyRPCBinaryLogWithCompatCodec(t *testing.T) {
    capture := reviewCaptureLogger{entries: make(chan *binlogpb.GrpcLogEntry, 32)}
    previous := binlog.GetLogger()
    binlog.SetLogger(capture)
    defer binlog.SetLogger(previous)
    listener := bufconn.Listen(1 << 20)
    server := grpc.NewServer(grpc.ForceServerCodec(reviewLegacyCodec{}))
    legacy.RegisterSearchServiceV3Server(server, reviewLegacyServer{})
    go server.Serve(listener)
    defer server.Stop()
    ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
