    cc, err := grpc.DialContext(ctx, "passthrough:///legacy", grpc.WithTransportCredentials(insecure.NewCredentials()), grpc.WithContextDialer(func(context.Context, string) (net.Conn, error) { return listener.Dial() }), grpc.WithDefaultCallOptions(grpc.ForceCodec(reviewLegacyCodec{})))
    if err != nil { t.Fatal(err) }
    defer cc.Close()
    response, err := legacy.NewSearchServiceV3Client(cc).Search(ctx, &legacy.SearchRequestV3{Query: "test"})
